from __future__ import annotations

from pathlib import Path
from .store import GraphStore
from .util import git_info


def export_markdown(root: Path, store: GraphStore, out: Path | None=None) -> Path:
    root=Path(root).resolve(); out=out or root/"PROJECT_GRAPH.md"
    stats=store.stats(); git=git_info(root); nodes=store.all_nodes(); edges=store.all_edges()
    names={n["id"]:n for n in nodes}
    lines=[
        "# Project Graph", "",
        "<!-- Generated by RepoGraph. Deterministic and safe to commit. -->", "",
        f"- Repository: `{root.name}`",
        f"- Branch: `{git.get('branch') or 'n/a'}`",
        f"- Commit: `{git.get('commit') or 'n/a'}`",
        f"- Files: **{stats['files']}**",
        f"- Nodes: **{stats['nodes']}**",
        f"- Edges: **{stats['edges']}**", "",
        "## Node Kinds", "",
        "| Kind | Count |", "|---|---:|",
    ]
    for k,v in stats["node_kinds"].items(): lines.append(f"| `{k}` | {v} |")
    lines += ["", "## Symbols", "", "| ID | Kind | Symbol | Location |", "|---|---|---|---|"]
    for n in nodes:
        if n["kind"]=="file": continue
        sig=(n.get("signature") or n["name"]).replace("|","\\|").replace("\n"," ")
        lines.append(f"| `{n['id']}` | `{n['kind']}` | `{sig[:180]}` | `{n['path']}:{n['line']}` |")
    lines += ["", "## Relationships", "", "| From | Relation | To |", "|---|---|---|"]
    for e in edges:
        a=names.get(e["src"]); b=names.get(e["dst"])
        if not a or not b: continue
        left=f"{a['name']} ({a['path']}:{a['line']})".replace("|","\\|")
        right=f"{b['name']} ({b['path']}:{b['line']})".replace("|","\\|")
        lines.append(f"| `{left}` | **{e['kind']}** | `{right}` |")
    lines += ["", "## Git Working Tree", ""]
    if git["changed"]:
        for c in git["changed"]: lines.append(f"- `{c['status']}` `{c['path']}`")
    else: lines.append("Clean working tree.")
    out.write_text("\n".join(lines)+"\n",encoding="utf-8")
    return out
